--
-- Table structure for table `tbl_users`
--

CREATE TABLE `tbl_users` (
  `user_id` int(11) NOT NULL,
  `role_id` int(11) NOT NULL,
  `dept_id` int(11) DEFAULT NULL,
  `assigned_program_head_id` int(11) DEFAULT NULL,
  `first_name` varchar(100) NOT NULL,
  `last_name` varchar(100) NOT NULL,
  `id_number` varchar(15) NOT NULL,
  `email` varchar(255) NOT NULL,
  `image` longblob NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `password_version` tinyint(4) NOT NULL DEFAULT 1,
  `login_count` int(11) NOT NULL DEFAULT 0,
  `contact_no` varchar(20) NOT NULL,
  `permission_mode` enum('default','custom') NOT NULL DEFAULT 'default',
  `module_permissions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`module_permissions`)),
  `status` enum('active','inactive','archive') NOT NULL DEFAULT 'active',
  `is_first_login` tinyint(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

